#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n; string e;
    cin >> n >> e;
    vector<pair<long long,int>> terms;
    int i = 0, len = e.size(), sign = 1;
    if (len && e[0] == '-') { sign = -1; i = 1; }
    while (i < len) {
        long long coef = 1;
        bool isPre = false;
        if (isdigit(e[i])) {
            coef = 0;
            while (i < len && isdigit(e[i])) coef = coef * 10 + (e[i++] - '0');
            if (i < len && e[i] == '*') i++;
        }
        if (i + 1 < len && e[i] == '+' && e[i+1] == '+') { isPre = true; i += 2; }
        if (i < len && e[i] == 'a') i++;
        if (i + 1 < len && e[i] == '+' && e[i+1] == '+') i += 2;
        terms.push_back({sign * coef, isPre});
        if (i < len && (e[i] == '+' || e[i] == '-')) { sign = (e[i] == '+') ? 1 : -1; i++; }
    }
    sort(terms.begin(), terms.end());
    long long total = 0;
    for (size_t p = 0; p < terms.size(); p++)
        total += terms[p].first * (n + (long long)p + terms[p].second);
    cout << total << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int S; double t; int A, B;
    cin >> S >> t >> A >> B;
    vector<double> X(S*4), Y(S*4);
    vector<double> T(S);
    for (int c = 0; c < S; c++) {
        double x1,y1,x2,y2,x3,y3; double ti;
        cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3 >> ti;
        double dx = 0, dy = 0;
        double px[3] = {x1,x2,x3}, py[3] = {y1,y2,y3};
        for (int k = 0; k < 3; k++) {
            int a = (k+1)%3, b = (k+2)%3;
            if ((px[a]-px[k])*(px[b]-px[k]) + (py[a]-py[k])*(py[b]-py[k]) == 0) {
                dx = px[a]+px[b]-px[k]; dy = py[a]+py[b]-py[k];
            }
        }
        X[c*4]=x1; Y[c*4]=y1; X[c*4+1]=x2; Y[c*4+1]=y2; X[c*4+2]=x3; Y[c*4+2]=y3; X[c*4+3]=dx; Y[c*4+3]=dy;
        T[c] = ti;
    }
    int N = S * 4;
    vector<double> dist(N, 1e18);
    auto cost = [&](int u, int v) {
        double d = hypot(X[u]-X[v], Y[u]-Y[v]);
        return (u/4 == v/4 ? T[u/4] : t) * d;
    };
    for (int u = 0; u < 4; u++) dist[(A-1)*4+u] = 0;
    vector<bool> vis(N, false);
    for (int it = 0; it < N; it++) {
        int u = -1;
        for (int j = 0; j < N; j++) if (!vis[j] && (u < 0 || dist[j] < dist[u])) u = j;
        if (u < 0 || dist[u] > 1e17) break;
        vis[u] = true;
        for (int v = 0; v < N; v++) if (v != u) {
            double w = cost(u, v);
            if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
        }
    }
    double best = 1e18;
    for (int u = 0; u < 4; u++) best = min(best, dist[(B-1)*4+u]);
    printf("%.1f\n", best);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
string s;
char type(int l, int r) {
    bool z = false, o = false;
    for (int i = l; i <= r; i++) (s[i]=='0') ? z = true : o = true;
    return (z && o) ? 'F' : (z ? 'B' : 'I');
}
void post(int l, int r) {
    if (l == r) { putchar(type(l, r)); return; }
    int m = (l + r) / 2;
    post(l, m); post(m + 1, r);
    putchar(type(l, r));
}
int main() {
    int n; cin >> n >> s;
    post(0, s.size() - 1);
    putchar('\n');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
long long gcd(long long a, long long b) { return b ? gcd(b, a % b) : a; }
bool check(long long x, long long a0, long long a1, long long b0, long long b1) {
    if (gcd(x, a0) != a1) return false;
    long long g = gcd(x, b0);
    return x / g * b0 == b1;
}
int main() {
    int n; cin >> n;
    while (n--) {
        long long a0, a1, b0, b1;
        cin >> a0 >> a1 >> b0 >> b1;
        long long cnt = 0;
        for (long long d = 1; d * d <= b1; d++)
            if (b1 % d == 0) {
                if (check(d, a0, a1, b0, b1)) cnt++;
                if (d * d != b1 && check(b1 / d, a0, a1, b0, b1)) cnt++;
            }
        cout << cnt << "\n";
    }
    return 0;
}

